from typing import Dict

def get_fe_command(command_name: str, **kwargs: Dict[str, str]) -> str:
    if command_name == "LV":
        if "Vd" in kwargs and "Vg" in kwargs:
            fe_command = f"{command_name} {kwargs['Vd']} {kwargs['Vg']}"
        else:
            raise ValueError("LV command requires Vd and Vg keyword arguments")
    elif command_name == "TDAC":
        if "Col" in kwargs and "Row" in kwargs and "Value" in kwargs:
            fe_command = f"{command_name} {kwargs['Col']} {kwargs['Row']} {kwargs['Value']}"
        else:
            raise ValueError("TDAC command requires Col, Row and Value keyword arguments")
    else:
        raise ValueError("Invalid command name")
    return fe_command

