def dumps(d, encoder=None):
    """Converts dictionary to toml string

    Args:
        d: Dictionary to be converted
        encoder: (optional) Specifies the encoder function to use

    Returns:
        TOML string representation of the dictionary

    Raises:
        TypeError: When a non-dictionary is passed"""
    if not isinstance(d, dict):
        raise TypeError('Input must be a dictionary')
    if encoder is None:
        encoder = toml.dumps
    return encoder(d)

